using namespace std;

locale L_system;                // Current system default
locale L_c("C");                // Standard "C" locale

const locale::category C_NUM = locale::numeric;
const locale::category C_TIME = locale::time;

// Overload 1: From C-string name
locale L_us("en_US.UTF-8");

// Overload 2: (existing_locale, new_name, category_mask)
// L_half inherits everything from L_us except time settings,
// which are taken from L_c ("C").
locale L_half(L_us, L_c, C_TIME);

// Overload 3: (existing_locale, std_name, category_mask)
// Replace only numeric settings of L_system with "de_DE" rules
locale L_german_num(L_system, "de_DE.UTF-8", C_NUM);
